function extractJsonFromMarkdown(text) {
  if (!text || typeof text !== "string") return null;

  // Extract JSON inside a fenced code block ```json ... ``` or ``` ... ```
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenced && fenced[1]) return fenced[1].trim();

  // Fallback: slice first {...} block
  const firstBrace = text.indexOf("{");
  const lastBrace = text.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return text.slice(firstBrace, lastBrace + 1).trim();
  }

  return null;
}

function assert(condition, message) {
  if (!condition) throw new Error("SchemaFail: " + message);
}

// 1) Get raw Gemini text (your node output path)
const rawText = $json?.content?.parts?.[0]?.text;
assert(rawText, "Missing content.parts[0].text from Gemini output");

// 2) Extract JSON string from markdown fence
const jsonString = extractJsonFromMarkdown(rawText);
assert(jsonString, "Could not extract JSON from Gemini text output");

// 3) Parse JSON
let obj;
try {
  obj = JSON.parse(jsonString);
} catch (e) {
  throw new Error("JSON parse failed: " + e.message + "\nExtracted:\n" + jsonString);
}

// 4) Overwrite placeholders with REAL inputs from the same item
// (this fixes cases where the model repeats "{{product_title}}" literally)
const inputTitle = $json.product_title ?? $json.productTitle ?? "";
const inputSize  = $json.product_size  ?? $json.productSize  ?? "";

obj.text_facts = obj.text_facts && typeof obj.text_facts === "object" ? obj.text_facts : {};
if (inputTitle) obj.text_facts.input_title = String(inputTitle);
if (inputSize)  obj.text_facts.input_size  = String(inputSize);

// 5) Minimal validation (lightweight Pydantic)
const allowedTypes = ["silk_scarf","cashmere_scarf","brooch","necklace","earrings","bracelet","other"];

assert(typeof obj.product_type === "string", "product_type must be string");
assert(allowedTypes.includes(obj.product_type), "Invalid product_type: " + obj.product_type);

assert(obj.visual_facts && typeof obj.visual_facts === "object", "visual_facts missing or not object");
const vf = obj.visual_facts;

for (const k of ["main_color","dominant_colors","motif","materials_visible","style_keywords","has_rhinestones","has_pearls"]) {
  assert(k in vf, "visual_facts." + k + " missing");
}

assert(typeof vf.main_color === "string", "visual_facts.main_color must be string");
assert(Array.isArray(vf.dominant_colors), "visual_facts.dominant_colors must be array");
assert(typeof vf.motif === "string", "visual_facts.motif must be string");
assert(Array.isArray(vf.materials_visible), "visual_facts.materials_visible must be array");
assert(Array.isArray(vf.style_keywords), "visual_facts.style_keywords must be array");
assert(typeof vf.has_rhinestones === "boolean", "visual_facts.has_rhinestones must be boolean");
assert(typeof vf.has_pearls === "boolean", "visual_facts.has_pearls must be boolean");

assert(obj.text_facts && typeof obj.text_facts === "object", "text_facts missing or not object");
assert(typeof obj.text_facts.input_title === "string", "text_facts.input_title must be string");
assert(typeof obj.text_facts.input_size === "string", "text_facts.input_size must be string");

assert(Array.isArray(obj.uncertainties), "uncertainties must be array");

// 6) Return clean object for next nodes
return [
  {
    json: {
      product_understanding: obj,
      _debug: {
        extracted_length: jsonString.length,
        used_title: obj.text_facts.input_title,
        used_size: obj.text_facts.input_size
