for (const k of ["attribute_group","attribute_name","attribute_value","confidence","warnings"]) {
  assert(k in obj, "Missing field: " + k);
}
assert(["general","jtl"].includes(obj.attribute_type), "Invalid attribute_type");
assert(Array.isArray(obj.warnings), "warnings must be array");
assert(typeof obj.confidence === "number", "confidence must be number");

// Optional: enforce enum behavior if allowed_values exist
if (Array.isArray($json.allowed_values) && $json.allowed_values.length > 0) {
  if (obj.value !== null && !$json.allowed_values.includes(obj.value)) {
    obj.warnings.push("not_in_allowed_values");
    obj.value = null;
  }
}

// 5) Return ONE clean attribute result
return [{
  json: {
    obj
  }
}];

const items = $input.all();

const normalized = items.map(item => {
  const d = item.json;

  return {
    attribute_group: d.attribute_group,
    attribute_name: d.attribute_name,
    attribute_value: d.attribute_value,
    attribute_type: "enum",      // oder single_line_text – je nach Attribut
    confidence: 1,
    warnings: []
  };
});

return [
  {
    json: {
      attributes_default: normalized
    }
  }
];

// Expecting ONE item with attribute_results: [{ obj: {...} }, ...]
const results = $json.attribute_results;

if (!Array.isArray(results)) {
  throw new Error("attribute_results is not an array");
}

const flattened = results.map(r => {
  if (!r.obj || typeof r.obj !== "object") {
    throw new Error("Missing obj in attribute_results entry");
  }

  return {
    attribute_group: r.obj.attribute_group,
    attribute_name: r.obj.attribute_name,
    attribute_value: r.obj.attribute_value,
    attribute_type: r.obj.attribute_type,
    confidence: r.obj.confidence ?? 1,
    warnings: Array.isArray(r.obj.warnings) ? r.obj.warnings : []
  };
});

return [
  {
    json: {
      attributes_generated: flattened
    }
  }
];

// 1) Read all incoming items (from both branches)
const items = $input.all().map(i => i.json);

// 2) Collect arrays ONLY (no implicit item guessing)
let defaults = [];
let generated = [];

for (const j of items) {
  if (Array.isArray(j.attributes_default)) {
    defaults = defaults.concat(j.attributes_default);
  }
  if (Array.isArray(j.attributes_generated)) {
    generated = generated.concat(j.attributes_generated);
  }
}

// 3) Hard guarantee: arrays only
if (!Array.isArray(defaults)) defaults = [];
if (!Array.isArray(generated)) generated = [];

// 4) Deduplicate: generated overrides defaults
function key(a) {
  return `${a.attribute_group ?? ""}::${a.attribute_name}`;
}

const map = new Map();

// defaults first
for (const a of defaults) {
  map.set(key(a), a);
}

// generated overwrites
// generated overwrites ONLY if it has a value
for (const a of generated) {
  const k = key(a);

  if (
    !map.has(k) ||
    (a.attribute_value !== null && a.attribute_value !== undefined)
  ) {
    map.set(k, a);
  }
}

// 5) Build helper KV-store (attribute_name → attribute_value)
const attributes_kv = {};

for (const a of map.values()) {
  if (
    typeof a.attribute_name === "string" &&
    a.attribute_name.length > 0
  ) {
    attributes_kv[a.attribute_name] = a.attribute_value;
  }
}

// 6) Final, clean output — ONE ITEM
return [{
  json: {
    attributes_all: Array.from(map.values()),
    attributes_kv, // 👈 helper object for fast access
    _debug: {
      defaults_count: defaults.length,
      generated_count: generated.length,
      final_count: map.size,
      kv_keys: Object.keys(attributes_kv).length
    }
  }
}];

function extractJson(text) {
  if (!text || typeof text !== "string") {
    throw new Error("LLM output is not a string");
  }

  // fenced ```json ... ```
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenced && fenced[1]) {
    return fenced[1].trim();
  }

  // fallback: first {...}
  const firstBrace = text.indexOf("{");
  const lastBrace = text.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return text.slice(firstBrace, lastBrace + 1).trim();
  }

  throw new Error("Could not extract JSON from LLM output");
}

