}

// 4) structure validation
for (const k of ["headline", "short_description", "long_description", "key_features"]) {
  assert(k in obj, "Missing field: " + k);
}

assert(typeof obj.headline === "string", "headline must be string");
assert(typeof obj.short_description === "string", "short_description must be string");
assert(typeof obj.long_description === "string", "long_description must be string");
assert(Array.isArray(obj.key_features), "key_features must be array");

// 5) content sanity checks
assert(obj.headline.trim().length > 5, "headline too short");
assert(obj.short_description.trim().length > 20, "short_description too short");
assert(obj.long_description.trim().length > 80, "long_description too short");

assert(
  obj.key_features.length >= 3,
  "key_features must contain at least 3 items"
);

obj.key_features.forEach((f, i) => {
  assert(typeof f === "string", `key_features[${i}] must be string`);
  assert(f.trim().length > 5, `key_features[${i}] too short`);
});

// 6) German language heuristic (lightweight, robust)
const germanMarkers = [
  " und ", " mit ", " aus ", " für ", " nicht ", " ohne ",
  "eine", "einer", "dieses", "diese", "hochwertig"
];

const fullText =
  obj.headline + " " +
  obj.short_description + " " +
  obj.long_description;

const germanScore = germanMarkers.filter(m => fullText.toLowerCase().includes(m)).length;

assert(
  germanScore >= 2,
  "Text does not appear to be German"
);

// 7) success – return clean object
return [{
