      key_features_count: obj.key_features.length
    }
  }
}];

/* ================================================================
   Fail-soft Amazon Description Validator & Normalizer
   ================================================================ */

/* ------------------------------------------------------------------
   Helpers
------------------------------------------------------------------ */

const errors = [];

function softAssert(cond, msg) {
  if (!cond) {
    errors.push(msg);
    return false;
  }
  return true;
}

function errorWrap(msg, original) {
  return `ERROR!: ${msg}\n\nORIGINAL:\n${original ?? ""}`;
}

function extractJson(text) {
  if (!text || typeof text !== "string") {
    return null;
  }

  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenced && fenced[1]) {
    return fenced[1].trim();
  }

  const firstBrace = text.indexOf("{");
  const lastBrace = text.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return text.slice(firstBrace, lastBrace + 1).trim();
  }

  return null;
}

/* ------------------------------------------------------------------
   1) get raw LLM output
------------------------------------------------------------------ */

const rawText =
  $json?.content?.parts?.[0]?.text ??
  $json?.text ??
  $json?.message ??
  "";

if (!rawText || typeof rawText !== "string") {
  return [{
    json: {
      amazon_description: {
        title: errorWrap("Missing LLM output text", ""),
        description: errorWrap("Missing LLM output text", ""),
        bullets: [errorWrap("Missing LLM output text", "")],
        backend_keywords: errorWrap("Missing LLM output text", "")
      },
      _errors: ["Missing LLM output text"]
    }
  }];
}

/* ------------------------------------------------------------------
   2) extract JSON
------------------------------------------------------------------ */

const jsonString = extractJson(rawText);

if (!jsonString) {
  return [{
    json: {
      amazon_description: {
        title: errorWrap("Could not extract JSON from LLM output", rawText),
        description: errorWrap("Could not extract JSON from LLM output", rawText),
        bullets: [errorWrap("Could not extract JSON from LLM output", rawText)],
        backend_keywords: errorWrap("Could not extract JSON from LLM output", rawText)
      },
      _errors: ["Could not extract JSON from LLM output"]
    }
  }];
}

/* ------------------------------------------------------------------
   3) parse JSON
------------------------------------------------------------------ */

let obj;
try {
  obj = JSON.parse(jsonString);
} catch (e) {
  return [{
    json: {
      amazon_description: {
        title: errorWrap("JSON parse failed", jsonString),
        description: errorWrap(e.message, jsonString),
        bullets: [errorWrap(e.message, jsonString)],
        backend_keywords: errorWrap(e.message, jsonString)
      },
      _errors: ["JSON parse failed: " + e.message]
    }
  }];
}

/* ------------------------------------------------------------------
   4) structure validation
------------------------------------------------------------------ */

softAssert("amazon_description" in obj, "Missing amazon_description object");

const ad = obj.amazon_description ?? {};

softAssert(typeof ad === "object", "amazon_description must be an object");
softAssert(typeof ad.title === "string", "title must be string");
softAssert(typeof ad.description === "string", "description must be string");
softAssert(Array.isArray(ad.bullets), "bullets must be array");
softAssert(typeof ad.backend_keywords === "string", "backend_keywords must be string");

ad.title = typeof ad.title === "string" ? ad.title : "";
ad.description = typeof ad.description === "string" ? ad.description : "";
ad.bullets = Array.isArray(ad.bullets) ? ad.bullets : [];
ad.backend_keywords = typeof ad.backend_keywords === "string" ? ad.backend_keywords : "";

/* ------------------------------------------------------------------
   5) content sanity checks
------------------------------------------------------------------ */

/* Title */
softAssert(ad.title.trim().length >= 20, "title too short");
softAssert(ad.title.length <= 200, "title exceeds Amazon limit (200 chars)");

/* Description */
softAssert(ad.description.trim().length >= 120, "description too short");
softAssert(ad.description.length <= 2000, "description exceeds Amazon limit (2000 chars)");
softAssert(!/<[^>]+>/.test(ad.description), "description must not contain HTML");

/* Bullets */
softAssert(ad.bullets.length >= 3 && ad.bullets.length <= 5, "bullets must contain 3–5 items");

ad.bullets = ad.bullets.map((b, i) => {
  if (typeof b !== "string") {
    errors.push(`bullets[${i}] must be string`);
    return errorWrap(`bullets[${i}] must be string`, String(b));
  }
  if (b.trim().length < 30) {
    errors.push(`bullets[${i}] too short`);
  }
  if (b.length > 255) {
    errors.push(`bullets[${i}] exceeds Amazon limit (255 chars)`);
  }
  return b;
});

/* Backend keywords */
softAssert(ad.backend_keywords.trim().length >= 50, "backend_keywords too short");
softAssert(ad.backend_keywords.length <= 1000, "backend_keywords exceeds Amazon limit (1000 chars)");

/* ------------------------------------------------------------------
   6) German language heuristic
------------------------------------------------------------------ */

const germanMarkers = [
  " und ", " mit ", " aus ", " für ", " ohne ", " nicht ",
  "hochwertig", "damen", "elegant",
  "handwäsche", "geeignet", "pflege"
];

const fullText =
  ad.title + " " +
  ad.description + " " +
  ad.bullets.join(" ") + " " +
  ad.backend_keywords;

const germanScore = germanMarkers.filter(m =>
  fullText.toLowerCase().includes(m)
).length;

softAssert(germanScore >= 3, "Text does not appear to be German");

/* ------------------------------------------------------------------
   7) finalize errors into fields
------------------------------------------------------------------ */

if (errors.length > 0) {
  const msg = errors.join(" | ");
  ad.title = errorWrap(msg, ad.title);
  ad.description = errorWrap(msg, ad.description);
  ad.bullets = ad.bullets.map(b => errorWrap(msg, b));
  ad.backend_keywords = errorWrap(msg, ad.backend_keywords);
}

/* ------------------------------------------------------------------
   8) return
------------------------------------------------------------------ */

return [{
  json: {
    amazon_description: ad,
    _errors: errors,
    _debug: {
      error_count: errors.length,
      german_marker_hits: germanScore,
      title_length: ad.title.length,
      description_length: ad.description.length,
      bullets_count: ad.bullets.length,
      backend_keywords_length: ad.backend_keywords.length
    }
  }
}];

