      },
      _errors: ["JSON parse failed: " + e.message]
    }
  }];
}

/* ------------------------------------------------------------------
   4) structure validation (soft)
------------------------------------------------------------------ */

softAssert("tiktok_description" in obj, "Missing field: tiktok_description");

const td = obj.tiktok_description ?? {};

softAssert(typeof td === "object", "tiktok_description must be an object");
softAssert(typeof td.titel === "string", "titel must be string");
softAssert(typeof td.description === "string", "description must be string");

/* Normalize empty fields */
td.titel = typeof td.titel === "string" ? td.titel : "";
td.description = typeof td.description === "string" ? td.description : "";

/* ------------------------------------------------------------------
   5) title checks (TikTok specific)
------------------------------------------------------------------ */

/* min length */
if (!softAssert(td.titel.trim().length >= 10, "titel too short")) {
  td.titel = errorWrap("titel too short", td.titel);
}

/* max 80 chars */
if (td.titel.length > 80) {
  const fallbackTitle =
    $('ProductFields')?.first()?.json?.product_title;

  if (fallbackTitle && typeof fallbackTitle === "string") {
    td.titel = fallbackTitle.trim().slice(0, 80);
  } else {
    td.titel = errorWrap(
      "titel exceeds 80 characters and no fallback available",
      td.titel
    );
  }
}

/* ------------------------------------------------------------------
   6) description checks (TikTok style)
------------------------------------------------------------------ */

const desc = td.description;

/* length */
softAssert(desc.trim().length >= 150, "description too short");
softAssert(desc.length <= 2200, "description too long");

/* no HTML */
softAssert(!/<[^>]+>/.test(desc), "description must not contain HTML");

/* emojis */
softAssert(/\p{Extended_Pictographic}/u.test(desc), "missing emojis");

/* line breaks */
softAssert(/\n/.test(desc), "missing line breaks");

/* bullet / list style */
const bulletCount =
  (desc.match(/^[•\-–—]/gm)?.length || 0) +
  (desc.match(/^[^\w\s]/gm)?.length || 0);

softAssert(
  bulletCount >= 2,
  "description should contain at least 2 bullet-style lines"
);

/* ------------------------------------------------------------------
   7) German language heuristic
------------------------------------------------------------------ */

const lowered = (td.titel + " " + desc).toLowerCase();

const germanMarkers = [
  " und ", " mit ", " aus ", " für ", " dein ", " deine ",
  "perfekt", "stil", "ideal"
];

const germanScore = germanMarkers.filter(m =>
  lowered.includes(m)
).length;

softAssert(germanScore >= 3, "Text does not appear to be German");

/* ------------------------------------------------------------------
   8) finalize errors into fields
------------------------------------------------------------------ */

if (errors.length > 0) {
  const msg = errors.join(" | ");
  td.titel = errorWrap(msg, td.titel);
  td.description = errorWrap(msg, td.description);
}

/* ------------------------------------------------------------------
   9) success return (loop-safe)
------------------------------------------------------------------ */

return [{
  json: {
    tiktok_description: td,
    _errors: errors,
    _debug: {
      error_count: errors.length,
      german_marker_hits: germanScore,
      title_length: td.titel.length,
      description_length: td.description.length,
      emoji_in_title: /\p{Extended_Pictographic}/u.test(td.titel),
      emoji_in_description: /\p{Extended_Pictographic}/u.test(td.description),
      bullet_like_lines: bulletCount,
      line_breaks: (td.description.match(/\n/g) || []).length
    }
  }
}];

