/* BUILD ONE FLAT CSV-READY OBJECT (WITH DEBUG)                       */
/* ================================================================== */

/* ------------------------------------------------------------------ */
/* INPUTS                                                             */
/* ------------------------------------------------------------------ */

const rawProductFields =
  $node["ProductFields"]?.json ?? {};

const attributesData =
  $node["MergeAllAttributes"]?.json ?? {};


/* take first item if present */
let descriptionsRootRaw = $input.first().json ?? {};
let descriptionsRoot;

/* Parse if stringified JSON */
if (typeof descriptionsRootRaw === "string") {
  try {
    descriptionsRoot = JSON.parse(descriptionsRootRaw);
  } catch (e) {
    throw new Error("Descriptions JSON could not be parsed");
  }
} else {
  descriptionsRoot = descriptionsRootRaw;
}


/* ================================================================== */
/* 1) CLEAN PRODUCT FIELDS                                            */
/* ================================================================== */

const EXCLUDE_PRODUCT_KEYS = new Set([
  "product_images",
  "product_category",
  "submittedAt",
  "formMode",
  "headers",
  "params",
  "query",
  "body",
  "webhookUrl",
  "executionMode",
  "perlengroesse",
  "farbsteinart",
  "durchmesser_anhaenger",
  "gesamtlaenge_kette",
  "product_typ"
]);

const cleanedProductFields = Object.fromEntries(
  Object.entries(rawProductFields).filter(
    ([key]) => !EXCLUDE_PRODUCT_KEYS.has(key)
  )
);

/* ================================================================== */
/* 2) EXTRACT JTL ATTRIBUTES (FLAT)                                   */
/* ================================================================== */

const attributesAll = Array.isArray(attributesData.attributes_all)
  ? attributesData.attributes_all
  : [];

const jtlAttributesFlat = Object.fromEntries(
  attributesAll
    .filter(a => a.attribute_group === "JTL")
    .map(a => [
      a.attribute_name,
      a.attribute_value
    ])
);

/* ================================================================== */
/* 3) FLATTEN DESCRIPTIONS                                            */
/* ================================================================== */

const flatDescriptions = {};

for (const [platformKey, platformObj] of Object.entries(descriptionsRoot)) {

  if (!platformKey.endsWith("_description")) continue;
  if (typeof platformObj !== "object" || platformObj === null) continue;

  const prefix = platformKey
    .replace(/_description$/, "")
    .toLowerCase();

  for (const [field, value] of Object.entries(platformObj)) {

    if (field === "title" || field === "titel") {
      flatDescriptions[`${prefix}_title`] = String(value);
      continue;
    }

    if (field === "description" || field === "description_html") {
      flatDescriptions[`${prefix}_description`] = String(value);
      continue;
    }

    if (Array.isArray(value) && field === "bullets") {
      continue;
    }

    if (
      typeof value === "string" ||
      typeof value === "number" ||
      typeof value === "boolean"
    ) {
      flatDescriptions[`${prefix}_${field}`] = String(value);
    }
  }
}

/* ================================================================== */
/* 4) MERGE EVERYTHING                                                */
/* ================================================================== */

const flatCsvObject = {
  ...cleanedProductFields,
  ...jtlAttributesFlat,
  ...flatDescriptions,

};

/* ================================================================== */
/* 5) FINAL CSV FORMAT + SORTED KEYS                                  */
/* ================================================================== */

const csvReadyObject = {};

const sortedKeys = Object.keys(flatCsvObject)
  .sort((a, b) => a.localeCompare(b));

for (const key of sortedKeys) {
  const value = flatCsvObject[key];

  if (typeof value === "number") {
    csvReadyObject[key] = Number.isInteger(value)
      ? String(value)
      : value.toString().replace(".", ",");
    continue;
  }

  if (typeof value === "object" && value !== null) {
    csvReadyObject[key] = JSON.stringify(value);
    continue;
  }

  csvReadyObject[key] = value;
}

/* ================================================================== */
/* OUTPUT                                                            */
/* ================================================================== */

return [{
  json: csvReadyObject
}];

/* ================================================================ */
/* FILTER ATTRIBUTES BY PRODUCT TYPE (ROBUST)                       */
/* ================================================================ */


const attributes = $input.all().map(item => item.json);

/* FIX: correct product type field */
const productTypeRaw =
  $node["ProductFields"]?.json?.product_typ ??
  $node["ProductFields"]?.json?.product_type ??
  "";

const productType = productTypeRaw
  .toString()
  .trim()
  .toLowerCase();

/* Normalize Kategorie safely */
function normalizeKategorie(kategorie) {
  if (!kategorie || typeof kategorie !== "string") return [];

  return kategorie
    .replace(/\s+/g, " ")   // remove newlines / tabs
    .split(",")
    .map(v => v.trim().toLowerCase())
    .filter(Boolean);
}

const filteredAttributes = attributes.filter(attr => {
  const katRaw = attr.Kategorie;

  if (!katRaw || typeof katRaw !== "string") return false;

  const categories = normalizeKategorie(katRaw);

  // keep if "all"
  if (categories.includes("all")) return true;

  // keep if product type matches
  return categories.includes(productType);
});

return filteredAttributes.map(attr => ({
  json: attr
}));
